import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] freq = new long[501];
        int maxV = 0;
        for (int i = 0; i < n; i++) {
            int v = (int) nextLong();
            freq[v]++;
            maxV = Math.max(maxV, v);
        }
        // more packs than the largest count can never beat 2 packs
        long best = Long.MAX_VALUE;
        for (int p = 2; p <= Math.max(2, maxV); p++) {
            long cost = 0;
            for (int v = 1; v <= 500; v++)
                if (freq[v] > 0) cost += freq[v] * ((p - v % p) % p); // top up to the next multiple of p
            best = Math.min(best, cost);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	freq := make([]int64, 501)
	maxV := 0
	for i := 0; i < n; i++ {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		freq[v]++
		maxV = max(maxV, v)
	}
	// more packs than the largest count can never beat 2 packs
	best := int64(math.MaxInt64)
	for p := 2; p <= max(2, maxV); p++ {
		var cost int64
		for v := 1; v <= 500; v++ {
			if freq[v] > 0 {
				cost += freq[v] * int64((p-v%p)%p) // top up to the next multiple of p
			}
		}
		best = min(best, cost)
	}
	fmt.Println(best)
}
